// Downloads page (P8-41, generated by scripts/gen-downloads.sh): puts the visitor's operating system first, and
// formats sizes and dates for the chosen language. Everything is local – no request of any kind (ADR 0009).
(() => {
  const list = document.getElementById("os-list");
  const query = new URLSearchParams(location.search).get("os"); // `?os=linux` (tests, or to look at another OS)

  const detect = () => {
    if (["windows", "macos", "linux"].includes(query)) return query;
    const ua = navigator.userAgent || "";
    const platform = (navigator.userAgentData?.platform || navigator.platform || "").toLowerCase();
    if (/android|iphone|ipad|ipod/i.test(ua)) return null; // phones and tablets: no desktop build fits
    // The platform first (the user agent string may be frozen or spoofed), the user agent as a fallback.
    if (platform) {
      if (platform.startsWith("win")) return "windows";
      if (platform.startsWith("mac")) return "macos";
      if (platform.includes("linux")) return "linux";
    }
    if (/Windows NT/.test(ua)) return "windows";
    if (/Macintosh|Mac OS X/.test(ua)) return "macos";
    if (/X11|Linux/.test(ua)) return "linux";
    return null;
  };

  const os = detect();
  if (list && os) {
    const section = list.querySelector(`section[data-os="${os}"]`);
    if (section) {
      list.prepend(section);
      section.classList.add("recommended");
      // The badge comes from a template, so only this section carries it (i18n.js translates it with the rest).
      const badge = document.getElementById("dl-badge")?.content.firstElementChild?.cloneNode(true);
      if (badge) section.querySelector("h2")?.append(" ", badge);
    }
  }

  // Apple Silicon or Intel: only Chromium tells (a local API, no request); then the matching .dmg is the main button.
  if (os === "macos" && !query && navigator.userAgentData?.getHighEntropyValues) {
    navigator.userAgentData
      .getHighEntropyValues(["architecture"])
      .then(({ architecture }) => {
        if (architecture !== "x86") return;
        for (const row of document.querySelectorAll('section[data-os="macos"] .dl-buttons')) {
          const intel = row.querySelector('[data-kind="x64"]');
          const arm = row.querySelector('[data-kind="arm64"]');
          if (!intel || !arm) continue;
          row.prepend(intel);
          intel.classList.remove("secondary");
          arm.classList.add("secondary");
        }
      })
      .catch(() => {});
  }

  const format = () => {
    const i18n = window.rusuiteI18n;
    const locale = i18n?.locale ?? "en";
    const number = new Intl.NumberFormat(locale, { minimumFractionDigits: 1, maximumFractionDigits: 1 });
    for (const el of document.querySelectorAll("[data-bytes]")) {
      const mb = number.format(Number(el.dataset.bytes) / 1e6);
      el.textContent = i18n ? i18n.t("portal.dl.size", { mb }) : `${mb} MB`;
    }
    const dates = new Intl.DateTimeFormat(locale, { dateStyle: "long", timeZone: "UTC" });
    for (const el of document.querySelectorAll("[data-date]")) {
      const d = new Date(`${el.dataset.date}T00:00:00Z`);
      if (!Number.isNaN(d.getTime()) && i18n) el.textContent = i18n.t("portal.dl.released", { date: dates.format(d) });
    }
  };
  // After each catalog load (i18n.js); until then the generated English texts stand.
  window.addEventListener("rusuite:locale", format);
})();
